INSERT INTO public.restaurants (id, name, description, image_url, cuisine, rating, delivery_time, delivery_fee, is_open, address) VALUES
('r1000000-0000-0000-0000-000000000001', 'Spice Garden', 'Authentic North Indian curries, tandoori grills, and slow-cooked rich gravies.', 'https://images.unsplash.com/photo-1585937421612-70a008356fbe?auto=format&fit=crop&w=800&q=80', 'North Indian, Mughlai, Tandoor', 4.6, '25-35 min', 40.00, true, '14 Heritage Boulevard, Indiranagar, Bangalore'),
('r1000000-0000-0000-0000-000000000002', 'Burger House', 'Gourmet smashed beef, grilled chicken, and loaded crispy plant burgers with artisanal fries.', 'https://images.unsplash.com/photo-1586190848861-99aa4a171e90?auto=format&fit=crop&w=800&q=80', 'Burgers, American, Fast Food', 4.5, '20-30 min', 35.00, true, '88 Sunset Strip, Koramangala, Bangalore'),
('r1000000-0000-0000-0000-000000000003', 'Pizza Corner', 'Traditional wood-fired Neapolitan sourdough pizzas, creamy pastas, and garlic dips.', 'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=800&q=80', 'Italian, Woodfired Pizza, Pasta', 4.7, '30-40 min', 45.00, true, '42 Tuscan Lane, Church Street, Bangalore'),
('r1000000-0000-0000-0000-000000000004', 'Chennai Tiffin', 'Crispy golden ghee roast dosas, fluffy steamed idlis, and authentic heritage filter coffee.', 'https://images.unsplash.com/photo-1668236543090-82eba5ee5976?auto=format&fit=crop&w=800&q=80', 'South Indian, Pure Veg, Breakfast', 4.8, '15-25 min', 25.00, true, '103 Temple Road, Malleshwaram, Bangalore'),
('r1000000-0000-0000-0000-000000000005', 'The Biryani Bowl', 'Signature dum-cooked aromatic basmati rice layered with tender marinated meat and saffron.', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', 'Biryani, Hyderabadi, Kebabs', 4.7, '30-40 min', 50.00, true, '55 Nizami Chowk, HSR Layout, Bangalore'),
('r1000000-0000-0000-0000-000000000006', 'Green Leaf', 'Nutrient-rich microgreen bowls, keto salads, cold-pressed elixirs, and sourdough toasts.', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 'Healthy, Salads, Vegan, Bowls', 4.4, '20-30 min', 30.00, true, '22 Orchard Way, Lavelle Road, Bangalore'),
('r1000000-0000-0000-0000-000000000007', 'Wok Express', 'Fiery wok-tossed Hakka noodles, crispy honey chilli lotus stem, and handcrafted dim sums.', 'https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&w=800&q=80', 'Pan-Asian, Chinese, Dim Sum', 4.5, '25-35 min', 40.00, true, '71 Dragon Arcade, Whitefield, Bangalore'),
('r1000000-0000-0000-0000-000000000008', 'Sweet Treats', 'Belgian chocolate truffle cakes, warm New York cookies, artisanal gelato, and cheesecakes.', 'https://images.unsplash.com/photo-1587314168485-3236d6710814?auto=format&fit=crop&w=800&q=80', 'Desserts, Bakery, Cakes, Gelato', 4.8, '20-30 min', 35.00, true, '19 Patisserie Street, MG Road, Bangalore'),
('r1000000-0000-0000-0000-000000000009', 'Cafe Mocha', 'Specialty single-origin Arabica brews, butter croissants, toasted panini, and iced matchas.', 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=800&q=80', 'Cafe, Artisanal Coffee, Sandwiches', 4.6, '15-25 min', 30.00, true, '5 Roast Avenue, Cunningham Road, Bangalore'),
('r1000000-0000-0000-0000-000000000010', 'South Spice', 'Fiery Chettinad pepper roasts, Malabar coconut curries, and coastal Mangalorean seafood.', 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?auto=format&fit=crop&w=800&q=80', 'Coastal, Chettinad, Kerala, Seafood', 4.6, '35-45 min', 45.00, true, '33 Coastal Way, Jayanagar, Bangalore');

